#!/usr/bin/env python3
"""Regenerate docs/api.md from src/api.yaml (a tiny subset of YAML)."""
from pathlib import Path

rows, row = [], {}
for line in Path("src/api.yaml").read_text(encoding="utf-8").splitlines():
    line = line.strip()
    if line.startswith("- "):
        if row:
            rows.append(row)
        row, line = {}, line[2:]
    if ":" in line and not line.endswith("endpoints:"):
        key, value = line.split(":", 1)
        row[key.strip()] = value.strip()
if row:
    rows.append(row)
out = ["# billing-api endpoints", "",
       "<!-- Generated by tools/gen_docs.py from src/api.yaml. Do not edit. -->", ""]
for r in rows:
    out += [f"## {r['method']} {r['path']}", "", r["summary"], ""]
Path("docs/api.md").write_text("\n".join(out), encoding="utf-8")
